# Decorators — modifying or enhancing functions

print("=== Basic decorator ===\n")

# A simple decorator
def timer(func):
    def wrapper(*args, **kwargs):
        import time
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} took {end - start:.4f} seconds")
        return result
    return wrapper

# Using the decorator
@timer
def slow_function():
    import time
    time.sleep(0.5)
    return "Done"

print(slow_function())

print("\n=== Decorator with parameters ===\n")

def repeat(times):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for i in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

@repeat(3)
def say_hello(name):
    print(f"Hello, {name}!")

say_hello("Aragorn")

print("\n=== Class method decorators ===\n")

class Character:
    def __init__(self, name, level):
        self.name = name
        self.level = level
        self._health = 100

    # Property decorator
    @property
    def health(self):
        return self._health

    @health.setter
    def health(self, value):
        if value < 0:
            self._health = 0
        elif value > 100:
            self._health = 100
        else:
            self._health = value

    # Class method
    @classmethod
    def create_hero(cls, name):
        return cls(name, 10)

    # Static method
    @staticmethod
    def is_valid_name(name):
        return len(name) >= 3

# Using properties
hero = Character("Aragorn", 15)
print(f"Initial health: {hero.health}")
hero.health = 80
print(f"After setting: {hero.health}")
hero.health = 150  # Capped at 100
print(f"After too high: {hero.health}")

# Using class method
hero2 = Character.create_hero("Legolas")
print(f"\nHero2: {hero2.name}, Level {hero2.level}")

# Using static method
print(f"Is 'Frodo' valid? {Character.is_valid_name('Frodo')}")
print(f"Is 'A' valid? {Character.is_valid_name('A')}")

