def log_call(func):
    def wrapper(*args, **kwargs):
        func_name = func.__name__
        print(f"Calling {func_name} with args: {args}, kwargs: {kwargs}")
        result = func(*args, **kwargs)
        print(f"{func_name} returned: {result}")
        return result
    return wrapper

def require_level(min_level):
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            if self.level >= min_level:
                return func(self, *args, **kwargs)
            else:
                print(f"Access denied! Need level {min_level} for {func.__name__}")
                return None
        return wrapper
    return decorator

class Player:
    def __init__(self, name, level):
        self.name = name
        self.level = level

    @log_call
    def speak(self, message):
        return f"{self.name} says: {message}"

    @require_level(10)
    def enter_dungeon(self):
        return f"{self.name} enters the dungeon!"

    @require_level(5)
    def rest(self):
        return f"{self.name} rests"

# Create player
player = Player("Aragorn", 5)

# Test methods
player.speak("Hello")
print()
player.enter_dungeon()
print()
player.rest()
